def language_name(exec_ctx: dict | None) -> str:
    """The user's language as the assertion names it (the engine's user_language code, or the code itself when unknown)."""
    language_code = str((exec_ctx or {}).get("user_language") or "user-language")
    return {
        "zh": "中文",
        "en": "English",
        "ja": "日本語",
        "ko": "한국어",
    }.get(language_code, language_code)


def interruption_block(exec_ctx: dict | None, _ENGINE_AIAP_DIR) -> str | None:
    """H3: the run this message landed on was interrupted (host restart, power cut, a turn that ended
    mid-run) and prepare_execution_context re-entered it instead of superseding it - or the human cancelled it with a cancel word.
    Tell the model to continue the node protocol (the engine kept every byte of run state), or to acknowledge the cancel."""
    if not exec_ctx:
        return None
    note = str(exec_ctx.get("human_note") or "").strip()
    cache_dir = exec_ctx.get("cache_dir")
    stop_id = exec_ctx.get("stop_id")
    public_note = exec_ctx.get("public_note")
    # the run this message landed on was stopped by the human (Web UI
    # Stop = stop execution, resumable); the engine routed the message by its rules and asks the model for one of six turns.
    if exec_ctx.get("stop_judge"):
        engine_dir = _ENGINE_AIAP_DIR.resolve()
        tools = engine_dir / "python_tools"
        judge_id = exec_ctx.get("judge_id")
        allowed = [str(a) for a in (exec_ctx.get("allowed") or [])]
        triggers = [str(t) for t in (exec_ctx.get("triggers") or [])]
        return (
            "[RUN STOPPED - JUDGE]\n"
            f"cache_dir: {cache_dir}\n"
            f"stop_id: {stop_id}\n"
            f"judge_id: {judge_id}\n"
            f"stopped_at: {exec_ctx.get('run_state_at_stop')} / node {exec_ctx.get('stopped_node')} (visit {exec_ctx.get('stopped_visit')})\n"
            f"human_message: {exec_ctx.get('human_message')}\n"
            f"allowed: {', '.join(allowed)}\n"
            f"triggers: {', '.join(triggers) or 'none'}\n"
            f"context_sha256: {exec_ctx.get('context_sha256')}\n"
            "[STOP CONTEXT]\n"
            f"{exec_ctx.get('context')}\n"
            "[END STOP CONTEXT]\n"
            "The human pressed Stop on this run; the engine kept every byte of run state and the run is NOT cancelled. The human "
            "then sent human_message. Decide, from the context above only, whether that message continues THIS run. After reading "
            "the entry, FIRST ENGINE ACTION (next_node and node_commit are refused with RUN_STOPPED_BY_HUMAN until then):\n"
            f"python {tools / 'stop_decision.py'} --cache-dir {cache_dir} --stop-id {stop_id} --judge-id {judge_id} "
            "--decision continue|ask [--recommendation continue_run|new_task|end_run|none --explanation \"...\" --advice \"...\"] "
            "--reason \"...\"\n"
            "Rules: choose continue ONLY when the message clearly points at this run (asks to go on, adds detail to the current step, "
            "or answers a question this run asked). Otherwise choose ask; when you believe the message is clearly a new task, still "
            "choose ask and set --recommendation new_task with your explanation. Never answer the stop question yourself. Write "
            "--reason, --explanation and --advice in the user's language.\n"
            "On {\"status\":\"CONTINUE\"}: print public_note verbatim as visible text, then run the next_action command it returns and "
            "continue the node protocol from the served node (resume.kind re_serve or same_occurrence); if the reply is WAITING_USER, "
            "re-present its public prompt and end the turn.\n"
            "On {\"status\":\"GATE\"}: print public_block_ref verbatim on its own line as visible text, then end the turn; do not call "
            "next_node.\n"
            "On {\"status\":\"REJECTED\"}: read code, allowed and triggers and submit again with an allowed decision."
        )
    if exec_ctx.get("stop_question"):
        # the question may have been opened by a supply interruption or a host restart, not by a Stop
        source = exec_ctx.get("question_source")
        if source == "supply_doubt":
            why = "The model supply was interrupted on this run and the engine asks the human whether to continue it once the supply is back. "
        elif source == "restart_doubt":
            why = "The host restarted while this run was RUNNING and the engine asks the human whether to continue it. "
        else:
            why = "The human pressed Stop on this run and the engine now asks the human whether the next message continues this run. "
        return (
            "[RUN STOPPED - QUESTION]\n"
            f"cache_dir: {cache_dir}\n"
            f"stop_id: {stop_id}\n"
            f"question_id: {exec_ctx.get('question_id')}\n"
            f"public_note: {public_note or '-'}\n"
            f"{why}"
            f"Your whole visible reply is{' public_note, then' if public_note else ''} this reference line exactly as written: "
            f"{exec_ctx.get('public_block_ref')} — nothing else. Do NOT read the engine entry and do NOT call next_node or "
            "node_commit (they are refused with RUN_STOPPED_BY_HUMAN). End the turn after the reference."
        )
    if exec_ctx.get("stop_new_task"):
        superseded_from = exec_ctx.get("superseded_from")
        return (
            "[RUN STOPPED - NEW TASK]\n"
            f"cache_dir: {cache_dir}\n"
            f"superseded_from: {superseded_from}\n"
            f"stop_id: {stop_id}\n"
            f"public_note: {public_note}\n"
            f"The human answered the stop question of run {superseded_from} with \"as a new task\". That run is ended (by the human) "
            "and THIS cache is a fresh run whose user_message is the human's original request as the engine recorded it; the chat "
            "message (\"2\" or the option label) was only the answer to the stop question. Print public_note verbatim as the first "
            "visible text, then execute this fresh run normally from the entry (Router.match first)."
        )
    if exec_ctx.get("stop_hold"):
        why = (
            "This message came from a schedule or another agent, so it was recorded and not executed."
            if exec_ctx.get("hold_reason") == "machine_message"
            else "The host re-entered the run before the human replied."
        )
        return (
            "[RUN STOPPED - HOLD]\n"
            f"cache_dir: {cache_dir}\n"
            f"stop_id: {stop_id}\n"
            f"stop_state: {exec_ctx.get('stop_state')}\n"
            f"public_note: {public_note}\n"
            f"This session's engine run was stopped by the human and waits for the human's next message. {why} Reply with exactly "
            "public_note (translate it to the user's language if that language is not Chinese), then end the turn. Do NOT read the "
            "engine entry and do NOT call next_node or node_commit."
        )
    if exec_ctx.get("supply_authorized") or exec_ctx.get("supply_hold"):
        # the run waits for its model supply - by the switch (authorized_by "switch") or by the human's
        # answer; a held machine message (supply_hold) and the authorized / noted / re-authorized replies are text-only turns
        why = (
            "A scheduled or agent message reached this run while the human's authorized wait is on; it was recorded, nothing runs."
            if exec_ctx.get("supply_hold")
            else "The host will re-enter this run by itself when the model supply is back (authorized_by \"switch\" = the "
                 "SOULBOT_RESUME_INTERRUPTED_RUNS=true setting, \"human:...\" = the human's answer); nothing runs now."
        )
        return (
            "[RUN SUPPLY WAIT - AUTHORIZED]\n"
            f"cache_dir: {cache_dir}\n"
            f"question_id: {exec_ctx.get('question_id') or '-'}\n"
            f"authorized_by: {exec_ctx.get('authorized_by') or '-'}\n"
            f"public_note: {public_note}\n"
            f"{why} Reply with exactly public_note (translate it to the user's language if that language is not Chinese), then end "
            "the turn. Do NOT read the engine entry and do NOT call next_node or node_commit."
        )
    if exec_ctx.get("interrupted_cancel"):
        if exec_ctx.get("stop_ended"):   # the run had been stopped by the human first (cancel word, or option 3 at the stop question)
            return (
                "[RUN CANCELLED]\n"
                f"cache_dir: {cache_dir}\n"
                f"stopped_by_human: {stop_id}; ended by: {exec_ctx.get('ended_by')}\n"
                f"public_note: {public_note}\n"
                f"The human had pressed Stop on this run first and now ended it with: {note!r}. Print public_note, then acknowledge "
                "briefly in the user's language; do not call next-node for that run and do not start new work unless the human asks "
                "for something new."
            )
        return (
            "[RUN CANCELLED]\n"
            f"cache_dir: {exec_ctx.get('cache_dir')}\n"
            f"The human cancelled the interrupted run with: {note!r}. Acknowledge briefly in the user's language; "
            "do not call next-node for that run and do not start new work unless the human asks for something new."
        )
    if exec_ctx.get("interrupted_confirm"):   # the switch is off - remind and wait, execute nothing
        original = str(exec_ctx.get("original_request") or "").strip().replace("\n", " ")
        node = exec_ctx.get("interrupted_node") or "?"
        reminder = f"上次运行「{original[:80]}」在节点 {node} 中断，尚未完成。回复「继续」续跑，回复「取消」放弃。"
        return (
            "[RUN INTERRUPTED - CONFIRM]\n"
            f"cache_dir: {exec_ctx.get('cache_dir')}\n"
            f"interrupted_node: {node}\n"
            f"original_request: {original}\n"
            f"pending_message: {note}\n"
            "An unfinished run of this session is waiting and SOULBOT_RESUME_INTERRUPTED_RUNS is off. Do NOT execute the pending "
            "message, do NOT read the engine entry and do NOT call next-node. Reply with exactly the following reminder (translate it "
            "to the user's language if that language is not Chinese), then end the turn:\n"
            f"{reminder}"
        )
    if exec_ctx.get("interrupted_reentry"):
        engine_dir = _ENGINE_AIAP_DIR.resolve()
        continued = ""
        if exec_ctx.get("stop_continue"):   # the same run, re-entered after a human Stop
            continued = (
                f"stopped_by_human: {stop_id}; continued by: {exec_ctx.get('continued_by')}\n"
                f"public_note: {public_note}\n"
                f"Report rule: this node's Report states the human's reply after the stop ({note!r}); when the reply answered the stop "
                f"question, it also states the recorded choice \"{exec_ctx.get('recorded_choice_label') or '-'}\". Print public_note "
                "verbatim before the first engine call.\n"
            )
        if exec_ctx.get("supply_resume"):   # the host's probe re-entered the run after a supply wait
            continued += (
                f"supply_resumed: {exec_ctx.get('question_id') or '-'}\n"
                f"public_note: {public_note}\n"
                "Print public_note verbatim before the first engine call; human_note holds the messages the human sent while the "
                "supply was down (may be empty).\n"
            )
        return (
            "[RUN INTERRUPTED - RESUMED]\n"
            f"cache_dir: {exec_ctx.get('cache_dir')}\n"
            f"human_note: {note}\n"
            f"{continued}"
            "The previous turn of this run ended without finishing (host restart, power cut or an interrupted turn); the engine "
            "kept every byte of run state and re-entered the SAME run. After reading the entry, FIRST ACTION: "
            f"python {engine_dir / 'python_tools' / 'next_node.py'} --cache-dir {exec_ctx.get('cache_dir')} ; continue the node "
            "protocol from the served node (resume.kind re_serve). Do not restart the program and do not treat human_note as a new "
            "request unless the served node asks for input; if the reply is WAITING_USER, re-present its public prompt and end the turn."
        )
    return None
